import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import type { PipelineRunRequest } from "@/api/types";
import { Search, Loader2 } from "lucide-react";

interface RunConfigFormProps {
  onSubmit: (config: PipelineRunRequest) => void;
  isLoading?: boolean;
}

export function RunConfigForm({ onSubmit, isLoading }: RunConfigFormProps) {
  const [domain, setDomain] = useState("");
  const [maxGaps, setMaxGaps] = useState(10);
  const [ideasPerRound, setIdeasPerRound] = useState(5);
  const [searchQueries, setSearchQueries] = useState("");

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const config: PipelineRunRequest = {
      domain: domain || undefined,
      max_gaps: maxGaps,
      ideas_per_round: ideasPerRound,
      search_queries: searchQueries
        ? searchQueries.split(",").map((q) => q.trim()).filter(Boolean)
        : undefined,
    };
    onSubmit(config);
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg">Pipeline Configuration</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">Research Domain</label>
            <Input
              placeholder="e.g., machine learning, nlp, computer vision"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Max Gaps</label>
              <Input
                type="number"
                min={1}
                max={50}
                value={maxGaps}
                onChange={(e) => setMaxGaps(Number(e.target.value))}
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Ideas Per Round</label>
              <Input
                type="number"
                min={1}
                max={20}
                value={ideasPerRound}
                onChange={(e) => setIdeasPerRound(Number(e.target.value))}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Search Queries (comma-separated)</label>
            <Input
              placeholder="transformer attention, few-shot learning"
              value={searchQueries}
              onChange={(e) => setSearchQueries(e.target.value)}
            />
          </div>

          <Button type="submit" disabled={isLoading} className="w-full">
            {isLoading ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <Search className="mr-2 h-4 w-4" />
            )}
            {isLoading ? "Starting..." : "Start Pipeline"}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

// --- Pipeline ---

export interface PipelineRunRequest {
  domain?: string;
  max_gaps?: number;
  generation_rounds?: number | null;
  ideas_per_round?: number | null;
  search_queries?: string[] | null;
  run_novelty?: boolean;
  run_feasibility?: boolean;
  run_synthesis?: boolean;
  export_format?: string;
}

export interface PipelineRunSummary {
  id: number;
  status: "pending" | "running" | "completed" | "failed";
  domain: string;
  current_stage: string | null;
  ideas_count: number;
  created_at: string;
  completed_at: string | null;
  error_message: string | null;
}

export interface PipelineRunDetail extends PipelineRunSummary {
  config: Record<string, unknown>;
  stages_completed: string[];
  ideas: IdeaSummary[];
}

export interface TriggerRunResponse {
  run_id: string;
  status: string;
}

export interface AutonomousCycleRequest {
  domain?: string;
  max_runs?: number;
}

export interface AutonomousCycleResponse {
  cycle_id: string;
  status: string;
  domain: string;
  max_runs: number;
}

// --- SSE ---

export interface StageProgressEvent {
  stage: string;
  index: number;
  total: number;
  elapsed: number;
}

export interface ProgressDoneEvent {
  done: true;
}

export interface HeartbeatEvent {
  heartbeat: true;
}

export type ProgressEvent = StageProgressEvent | ProgressDoneEvent | HeartbeatEvent;

// --- Ideas ---

export interface IdeaSummary {
  id: number;
  title: string;
  domain: string;
  novelty_score: number | null;
  feasibility_score: number | null;
  overall_score: number | null;
